from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those groups into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    def is_balanced(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    def get_group_start_end_indices(s: str) -> List[int]:
        start_indices = []
        end_indices = []
        balance = 0
        for i, char in enumerate(s):
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance == 0:
                start_indices.append(i)
                end_indices.append(i)
        return list(zip(start_indices, end_indices))

    def extract_group(s: str, start_index: int, end_index: int) -> str:
        return s[start_index:end_index + 1]

    result = []
    indices = get_group_start_end_indices(paren_string)
    for start, end in indices:
        if is_balanced(paren_string[start:end + 1]):
            result.append(extract_group(paren_string, start, end))

    return result


# Example usage
if __name__ == "__main__":
    print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

