def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    """Find the largest prime value in the list and return the sum of its digits."""
    max_prime = -1
    for num in lst:
        if is_prime(num):
            max_prime = max(max_prime, num)

    if max_prime == -1:
        return 0  # No prime numbers found

    digit_sum = sum(int(digit) for digit in str(max_prime))
    return digit_sum

